import os

from taf.transport.ssh import connect
from ute_common_bts.fsm import FsmServices
from ute_common_util.decorators.retry import retry_until_no_exception_or_timeout

from ..exception import NotSupportedProductException
from ..report.status import StatusPrinter
from ..utils.directories import Directories
from ..utils.logger import logger
from .flexi.config import DefaultConfig
from .flexi.fsm import DCMFileCollector, WMPFileCollector


class EnbUtil:
    """Class to organize enb actions"""

    def backup_config(self, product_type, load_prefix=".", log_level="INFO"):
        """Method used for backing up enb config

        :param string product_type: Type of product ['wmp', 'dcm']
        :param string load_prefix:  Prefix for the location
        :param string log_level:    Set if 'debug' level needed instead of 'info'

        :note: Backup files should be collected before test where it is possible to connect to FSM.
               In case of error ReportAction will use backup files to report test results.
        """
        status = StatusPrinter()
        dirs = Directories(base_name="rp_backup", base_dir="/tmp")
        dirs.create_dir("bts_report_backup")

        status.print_backup_start_info(dirs.dir_path)
        logger.set_logger_level(log_level if log_level else "INFO")

        product_type = product_type if product_type else "wmp"
        file_collector = self.create_file_collector(product_type)

        self.enable_ssh_rnd_ports(product_type)
        file_collector.download_config_files(dirs.dir_path)
        self.save_sw_version(dirs, file_collector, load_prefix, "bts_sw_version")

        status.print_backup_end_info()

    @staticmethod
    def create_file_collector(product_type):
        """Method used for creating file collector

        :param string product_type: Type of product ['wmp', 'dcm']
        """
        supported = {
            "wmp": WMPFileCollector,
            "dcm": DCMFileCollector,
        }
        if product_type in supported:
            return supported[product_type](DefaultConfig())
        else:
            raise NotSupportedProductException("Wrong product type provided/detected")

    @staticmethod
    @retry_until_no_exception_or_timeout(timeout=300, delay=1, on_timeout=RuntimeError)
    def enable_ssh_rnd_ports(product_type, no_config_flag=False):
        """Method used to enable ssh/rnd ports
        :param string   product_type:    Type of product ['wmp', 'dcm']
        :param bool      no_config_flag: Flag that determines if config files should be downloaded
        """
        if "wmp" != product_type:
            return
        if EnbUtil.is_ssh_working():
            logger.info("SSH/RND ports already enabled")
        else:
            logger.info("Enabling SSH/RND ports")
            FsmServices().enable_ssh()
            FsmServices().enable_rnd_ports()

    @staticmethod
    def save_sw_version(dirs, file_collector, prefix, filename):
        """Method used for saving software version"""
        with open(os.path.join(dirs.dir_path, filename), "w") as f:
            f.write(file_collector.find_sw_version(dirs.dir_path, prefix))

    @staticmethod
    def is_ssh_working():
        """Check if SSH is working"""
        try:
            logger.info("Checking if SSH is already enabled")
            ssh_connection = connect('192.168.255.1',
                                     'toor4nsn',
                                     password='oZPS0POrRieRtu',
                                     port=22)
            ssh_connection.execute('ls')
            ssh_connection.disconnect()
            return True
        except Exception as e:
            logger.debug(f"Cannot SSH to eNB because of: {str(e)}")
            return False
